(function(E){ const x = E["sales-m4"] = E["sales-m4"] || {units:{}}; x.units["sales-4-1"] = {"grammar":{"id":"c-sales-4-1-g","level":"B1","course":"sales","unit":"sales-4-1","title":"Passing on a complaint: She said..., She told me..., She asked if...","titleTr":"Bir şikâyeti aktarmak: She said..., She told me..., She asked if...","titleFa":"شکایت را به تیم منتقل کن: She said...، She told me...، She asked if...","formsTable":{"headers":{"en":["She said (her words)","You pass it on"],"tr":["Söylediği (kendi sözleri)","Senin aktarman"],"fa":["حرف خودش","انتقال تو"]},"rows":[["\"The cartons are wet.\"","She said the cartons were wet."],["\"The goods are new.\"","She told me the goods were new."],["\"Will you pay for them?\"","She asked if we would pay for them."],["\"Does anyone check the boxes?\"","She asked if anyone checked the boxes."]]},"wrong":"She said me that the cartons were wet.","right":"She told me that the cartons were wet.","blank":{"sentence":"The buyer ___ me that 40 cartons had arrived damaged.","word":"told","distractors":["said","spoke"]},"wrong2":"She asked would we pay for the damage.","right2":"She asked if we would pay for the damage.","blank2":{"sentence":"She asked ___ we could send new cartons by Friday.","word":"if","distractors":["that","did"]},"expParts":{"tryFrom":"blank","rule":[{"en":"said + her words; told + person + her words.","tr":"said + onun sözleri; told + kişi + onun sözleri.","fa":"بعد از said خود حرف می‌آید؛ بعد از told اول شخص و بعد حرف.","ex":"She said the cartons were wet. She told me the cartons were wet."},{"en":"Never 'said me': use 'told me' or 'said to me'.","tr":"Asla 'said me' değil: 'told me' ya da 'said to me'.","fa":"هرگز said me نگو؛ بگو told me یا said to me.","ex":"She told me the goods were new."},{"en":"Questions: asked if, or asked + question word, statement order.","tr":"Sorular: asked if ya da asked + soru kelimesi, düz cümle sırası.","fa":"در سؤال‌ها asked if می‌آید، یا asked با کلمه‌ی پرسشی؛ و بعدش ترتیب جمله‌ی خبری.","ex":"She asked if we would pay for the damage."},{"en":"Tenses usually move back: will to would, is to was.","tr":"Zamanlar genellikle geri kayar: will'den would'a, is'ten was'a.","fa":"زمان‌ها معمولاً یک قدم عقب می‌روند: will می‌شود would و is می‌شود was.","ex":"She said she would send photos."}],"test":{"en":"Is there a person right after the verb? Use told. No person? Use said.","tr":"Fiilden hemen sonra bir kişi var mı? told kullan. Kişi yok mu? said kullan.","fa":"درست بعد از فعل شخصی آمده؟ told بیاور. شخصی نیامده؟ said بیاور."},"contrast":{"en":"Turkish 'bana dedi ki' and Persian «به من گفت» put the person after 'said', so learners write 'said me'. In English, 'told' takes the person; 'said' does not.","tr":"Türkçede 'bana dedi ki' deriz; bu yüzden İngilizcede 'said me' yazılıyor. İngilizcede kişiyi told alır: told me. said doğrudan kişi almaz.","fa":"در فارسی می‌گوییم «به من گفت»؛ برای همین خیلی از ما می‌نویسیم said me. در انگلیسی شخص بعد از told می‌آید: told me. بعد از said شخص مستقیم نمی‌آید."}},"errorWatch":[{"find":["said me","said us","said him","told that"],"fix":{"en":"told + person, said + words: 'She told me...', 'She said that...'.","tr":"told + kişi, said + söz: 'She told me...', 'She said that...'.","fa":"بعد از told شخص می‌آید و بعد از said خود حرف: «She told me...» و «She said that...»."}},{"find":["asked would","asked did","asked can","asked will","asked could","asked do","asked does"],"fix":{"en":"Pass on a question with if and statement order: 'She asked if we would pay.'","tr":"Bir soruyu if ve düz cümle sırasıyla aktar: 'She asked if we would pay.'","fa":"سؤال را با if و ترتیب جمله‌ی خبری منتقل کن: «She asked if we would pay.»"}}]},"b2":{"id":"c-sales-4-1-b2","level":"B2","track":"B2","course":"sales","unit":"sales-4-1","title":"What we did about it: offered to, apologised for, agreed to","titleTr":"Bu konuda ne yaptık: offered to, apologised for, agreed to","titleFa":"چه کردیم: offered to، apologised for، agreed to","formsTable":{"headers":{"en":["Verb","Pattern","Example"],"tr":["Fiil","Kalıp","Örnek"],"fa":["فعل","الگو","مثال"]},"rows":[["offer / promise / agree","+ to + verb","We offered to replace the cartons."],["apologise","+ for + -ing","She apologised for sending the wrong label."],["suggest","+ -ing","He suggested changing the pallet."]]},"wrong":"We apologised to send the wrong label.","right":"We apologised for sending the wrong label.","blank":{"sentence":"We offered ___ the damaged cartons.","word":"to replace","distractors":["replacing","replace"]},"wrong2":"The manager suggested to change the pallet.","right2":"The manager suggested changing the pallet.","blank2":{"sentence":"The buyer agreed ___ the old cartons for inspection.","word":"to keep","distractors":["keeping","keep"]},"expParts":{"tryFrom":"blank2","rule":[{"en":"offer / promise / agree + to + verb.","tr":"offer / promise / agree + to + fiil.","fa":"بعد از offer، promise و agree اول to می‌آید و بعد فعل.","ex":"We offered to replace the cartons."},{"en":"apologise + for + -ing.","tr":"apologise + for + -ing.","fa":"بعد از apologise for فعل با ing می‌آید.","ex":"She apologised for sending the wrong label."},{"en":"suggest + -ing (or suggest that + clause).","tr":"suggest + -ing (ya da suggest that + yan cümle).","fa":"بعد از suggest فعل با ing می‌آید، یا that و یک جمله.","ex":"He suggested changing the pallet."}],"test":{"en":"Say the verb, then its pattern, out loud: 'offer to', 'apologise for -ing', 'suggest -ing'.","tr":"Fiili ve kalıbını yüksek sesle söyle: 'offer to', 'apologise for -ing', 'suggest -ing'.","fa":"فعل را با الگویش بلند بگو: offer to، apologise for -ing، suggest -ing."},"contrast":{"en":"Turkish 'değiştirmeyi teklif etti' and Persian «پیشنهاد داد که عوضش کند» use one pattern for every verb. English verbs each choose their own: to, for + -ing, or -ing.","tr":"Türkçede 'değiştirmeyi teklif etti' der ve her fiilde aynı kalıbı kullanırız. İngilizcede her fiil kendi kalıbını seçer: to, for + -ing ya da -ing.","fa":"در فارسی می‌گوییم «پیشنهاد داد که عوضش کند» و برای همه‌ی فعل‌ها یک الگو داریم. در انگلیسی هر فعل الگوی خودش را دارد: to، for + ‎-ing یا ‎-ing."}},"errorWatch":[{"find":["apologised to send","apologized to send","apologised to give","offered paying","offered pay","suggested to change","suggested to send","agreed keeping","promised changing"],"fix":{"en":"Check the verb's pattern: offer to pay, apologise for sending, suggest changing.","tr":"Fiilin kalıbını kontrol et: offer to pay, apologise for sending, suggest changing.","fa":"الگوی فعل را بررسی کن: offer to pay، apologise for sending، suggest changing."}}],"useIn":{"en":"B2: in the report or the email, use two reporting verbs (for example 'offered to', 'apologised for').","tr":"B2: raporda ya da e-postada iki aktarma fiili kullan (örneğin 'offered to', 'apologised for').","fa":"مسیر B2: در گزارش یا ایمیل دو فعل نقل‌قول به کار ببر (مثلاً offered to و apologised for)."},"exitItem":{"from":"sales-4-1","kind":"blank","prompt":"The supplier promised ___ the packing for all export orders.","options":["changing","to change","change"],"correct":1}},"vocab":{"id":"c-sales-4-1-v","level":"B1","category":"vocab","course":"sales","unit":"sales-4-1","goals":["career"],"title":{"en":"Complaints and fixes","tr":"Şikâyetler ve çözümler","fa":"شکایت و راه‌حل"},"cards":[{"word":"complaint","sentence":"We received a complaint about the labels.","meaning":{"en":"When a customer says something is wrong.","tr":"şikâyet.","fa":"شکایت"}},{"word":"refund","sentence":"The customer asked for a refund.","meaning":{"en":"Money paid back to a customer.","tr":"para iadesi.","fa":"بازگرداندن پول"}},{"word":"replacement","sentence":"A replacement will be shipped tomorrow.","meaning":{"en":"A new product sent instead of a bad one.","tr":"yenisiyle değişim, yedek ürün.","fa":"کالای جایگزین"}},{"word":"claim","sentence":"We sent the insurance claim on Monday.","meaning":{"en":"A formal request for money after loss or damage.","tr":"tazmin talebi","fa":"درخواست خسارت"}},{"word":"review","sentence":"One bad review can cost you orders.","meaning":{"en":"A customer's public opinion of a product.","tr":"(müşteri) yorumu, değerlendirme.","fa":"نظر مشتری؛ نقد"}},{"word":"apologise","sentence":"We apologised for the mistake.","gap":"apologised","accept":["apologised","apologized","apologise"],"meaning":{"en":"To say sorry.","tr":"özür dilemek.","fa":"عذرخواهی کردن"}},{"word":"fault","sentence":"It was our fault, not the carrier's.","meaning":{"en":"A mistake that makes something go wrong.","tr":"kusur, hata.","fa":"ایراد؛ تقصیر"}},{"word":"put right","sentence":"How can we put it right?","gap":"put it right","accept":["put it right","put right"],"meaning":{"en":"To correct a problem.","tr":"düzeltmek, telafi etmek.","fa":"درست کردن؛ جبران کردن"}},{"word":"customer care","sentence":"Customer care answers within a day.","meaning":{"en":"The team that helps customers after they buy.","tr":"müşteri hizmetleri.","fa":"خدمات مشتریان"}},{"word":"compensation","sentence":"We paid compensation for the lost cartons.","meaning":{"en":"Money paid for a loss or damage.","tr":"tazminat.","fa":"غرامت؛ جبران خسارت"}}]},"judge":{"id":"c-sales-4-1-j","course":"sales","unit":"sales-4-1","type":"judge","title":{"en":"A good reply to a complaint?","tr":"Şikâyete iyi bir cevap mı?","fa":"جواب خوب به یک شکایت؟"},"prompt":"A buyer writes: \"40 of our 200 cartons arrived wet.\" Four replies.","parts":["Clear sorry","Shows you listened","Fix and date"],"instruction":{"en":"Tap what each reply has. The reply to send has all three.","tr":"Her cevapta ne olduğuna dokun. Gönderilecek cevapta üçü de var.","fa":"روی چیزهایی که هر جواب دارد بزن. جوابی که باید بفرستی هر سه را دارد."},"items":[{"by":"New rep","answer":"The goods left our warehouse dry, so this is the carrier's problem. Please contact them.","present":[],"fix":{"en":"It may be true, but you have sent the work to the customer. Say sorry and take the claim on yourself.","tr":"Doğru olabilir ama işi müşteriye yıktın. Özür dile ve tazmin işini üstlen.","fa":"شاید درست باشد، ولی کار را گردن مشتری انداختی. عذرخواهی کن و پیگیری خسارت را به عهده بگیر."}},{"by":"AI tool","answer":"We deeply apologise for any inconvenience this may have caused and value your business greatly.","present":["Clear sorry"],"fix":{"en":"A sorry with no facts. Name the 40 wet cartons, and give a fix and a date.","tr":"Bilgi içermeyen bir özür. 40 ıslak koliyi belirt, çözüm ve tarih ver.","fa":"عذرخواهی کرده‌ای، ولی هیچ واقعیتی نگفته‌ای. به ۴۰ کارتن خیس اشاره کن و راه‌حل و تاریخ بده."}},{"by":"Sales rep","answer":"So 40 of your 200 cartons arrived wet. We'll ship 40 new ones by Friday.","present":["Shows you listened","Fix and date"],"fix":{"en":"Clear and fast, but you never said sorry. Add it after the summary.","tr":"Net ve hızlı ama özür dilemedin. Özetten sonra ekle.","fa":"روشن و سریع است، ولی عذرخواهی نکردی. بعد از خلاصه آن را اضافه کن."}},{"by":"Good model","answer":"You told me that 40 of your 200 cartons arrived wet. I'm sorry about that. We'll ship 40 new cartons by Friday, and we'll deal with the insurance ourselves.","present":["Clear sorry","Shows you listened","Fix and date"],"fix":null}]},"speaking":{"id":"sales-4-1","course":"sales","unit":"sales-4-1","topic":{"en":"The complaint call, and passing it on","tr":"Şikâyet görüşmesi ve ekibe aktarma","fa":"تماس شکایت و انتقال آن به تیم"},"warmup":{"en":"Remember a complaint you made as a customer. What did you want most?","tr":"Müşteri olarak yaptığın bir şikâyeti hatırla. En çok ne istiyordun?","fa":"شکایتی را که به‌عنوان مشتری کرده‌ای به یاد بیاور. بیشتر از همه چه می‌خواستی؟"},"questions":[{"en":"A buyer calls: 'Half the labels are wrong, and we can't sell the goods.' Summarise, say sorry, ask for what you need.","tr":"Bir alıcı arıyor: 'Half the labels are wrong, and we can't sell the goods.' Özetle, özür dile, gereken şeyi iste.","fa":"خریداری زنگ می‌زند: «Half the labels are wrong, and we can't sell the goods.» خلاصه کن، عذرخواهی کن و چیزی را که لازم داری بخواه."},{"en":"Offer a fix with a date, and say when you will call back.","tr":"Tarihli bir çözüm öner ve ne zaman geri arayacağını söyle.","fa":"راه‌حلی با تاریخ پیشنهاد کن و بگو کی دوباره زنگ می‌زنی."},{"en":"Now tell your manager what the customer said. Use said, told me and asked if.","tr":"Şimdi yöneticine müşterinin ne dediğini anlat. Said, told me ve asked if kullan.","fa":"حالا به مدیرت بگو مشتری چه گفت. از said، told me و asked if استفاده کن."}],"followups":[{"en":"What one thing would you change so this never happens again?","tr":"Bunun bir daha olmaması için tek bir şeyi değiştirecek olsan ne olurdu?","fa":"اگر بخواهی یک چیز را عوض کنی تا این اتفاق دیگر نیفتد، آن چیز چیست؟"}],"expressions":[{"phrase":"Let me make sure I have this right.","meaning":{"en":"Starts your summary.","tr":"Özetini başlatır.","fa":"خلاصه‌ات را شروع می‌کند."}},{"phrase":"I'm sorry about ...","meaning":{"en":"Says sorry for the exact thing.","tr":"Tam olarak o şey için özür diler.","fa":"برای همان موضوع مشخص عذرخواهی می‌کند."}},{"phrase":"She told me that ...","meaning":{"en":"Passes on the customer's words.","tr":"Müşterinin sözlerini aktarır.","fa":"حرف مشتری را منتقل می‌کند."}}],"model":"Let me make sure I have this right. Half the labels are wrong, and you can't sell the goods. I'm sorry about that. Could you send me one photo? We'll send new labels by air tomorrow. I'll call you on Thursday to check. Later, to my manager: She told me that half the labels were wrong. She asked if we could send new ones.","selfCheck":[{"en":"I summarised before I explained.","tr":"Açıklamadan önce özetledim.","fa":"قبل از توضیح دادن خلاصه کردم."},{"en":"I said sorry for the exact problem.","tr":"Tam olarak o sorun için özür diledim.","fa":"برای همان مشکل مشخص عذرخواهی کردم."},{"en":"I gave a fix and a date.","tr":"Bir çözüm ve bir tarih verdim.","fa":"راه‌حل و تاریخ دادم."},{"en":"I used told + person and asked if.","tr":"Told + kişi ve asked if kullandım.","fa":"told را با شخص به کار بردم و asked if را هم درست گفتم."}]},"writing":{"id":"c-sales-4-1-w","course":"sales","unit":"sales-4-1","type":"writing","difficulty":"medium","modelBy":"FEschool","title":{"en":"Your reply to a complaint","tr":"Şikâyete cevabın","fa":"جواب تو به یک شکایت"},"portfolio":"sales-final-6","prompt":{"en":"Use a real complaint, or: a buyer writes that 40 of 200 cartons arrived wet; your manager agrees to replace them at your cost by Friday, and your company handles the insurance claim. Write the reply (70-100 words): show you listened, say sorry for the exact thing, explain what you will do and by when, say who handles the insurance, and say one thing you will change.","tr":"Gerçek bir şikâyet ya da şunu kullan: bir alıcı 200 kolinin 40'ının ıslak geldiğini yazıyor; yöneticin bunları cuma gününe kadar masrafı size ait olmak üzere değiştirmeyi kabul ediyor, sigorta talebiyle de şirketin ilgileniyor. Cevabı yaz (70-100 kelime): dinlediğini göster, tam olarak o şey için özür dile, ne yapacağını ve ne zamana kadar yapacağını açıkla, sigortayla kimin ilgileneceğini söyle ve değiştireceğin bir şeyi belirt.","fa":"از یک شکایت واقعی یا این استفاده کن: خریداری می‌نویسد ۴۰ کارتن از ۲۰۰ کارتن خیس رسیده است؛ مدیرت موافق است تا جمعه با هزینه‌ی خودتان عوضشان کنید و شرکتت پیگیر بیمه است. جواب را بنویس (۷۰ تا ۱۰۰ کلمه): نشان بده گوش داده‌ای، برای همان موضوع عذرخواهی کن، توضیح بده چه می‌کنی و تا کی، بگو چه کسی پیگیر بیمه است و بگو چه چیزی را تغییر می‌دهی."},"model":"Dear Ms Ortega,\n\nThank you for telling us so quickly. You told me that 40 of your 200 cartons arrived wet, and I am sorry about that. We will ship 40 new cartons by Friday, at our cost. Please keep the wet cartons until the claim is closed. We will deal with the insurance claim ourselves. From now on, we will wrap every pallet in plastic before loading. I will call you on Friday to confirm.\n\nBest regards","frame":"Dear ___,\n\nThank you for ___. You told me that ___, and I am sorry about that. We will ___ by ___. Please ___. We will deal with ___ ourselves. From now on, we will ___. I will call you on ___.\n\nBest regards","words":[{"word":"You told me"},{"word":"I am sorry"},{"word":"From now on"}],"minWords":60,"minSentences":5,"rubric":["Task done: summary, sorry, fix with a date, who does what, one change","Organised: listening first, the fix next, the change last","Language: told + person; will for promises","Tone: calm, no excuses; the customer has less work to do"],"rubricI18n":{"tr":["Görev: özet, özür, tarihli çözüm, kim ne yapıyor, bir değişiklik","Düzen: önce dinleme, sonra çözüm, en sonda değişiklik","Dil: told + kişi; sözler için will","Üslup: sakin, bahanesiz; müşterinin işi azalıyor"],"fa":["کامل بودن کار: خلاصه، عذرخواهی، راه‌حل با تاریخ، مسئولیت‌ها، یک تغییر","نظم: اول گوش دادن، بعد راه‌حل، آخر تغییر","زبان: told با شخص؛ will برای قول‌ها","لحن: آرام و بدون بهانه؛ کار مشتری کمتر می‌شود"]}},"exit":{"id":"c-sales-4-1-x","course":"sales","unit":"sales-4-1","type":"exit","items":[{"from":"sales-4-1","kind":"blank","prompt":"The customer ___ that the labels were wrong.","options":["said me","said","told"],"correct":1,"point":2},{"from":"sales-4-1","kind":"mcq","prompt":"What should you do first when a customer complains?","options":["Explain whose fault it was.","Let them finish, then summarise.","Offer money."],"correct":1,"point":1},{"from":"sales-4-1","kind":"mcq","prompt":"Which fix reduces the customer's effort?","options":["Please call the carrier yourself.","Please write to our other department.","We'll handle the insurance claim ourselves."],"correct":2,"point":1},{"from":"sales-3-3","kind":"blank","prompt":"The invoice ___ to you by email yesterday.","options":["was sent","was send","sent"],"correct":0},{"from":"sales-3-1","kind":"blank","prompt":"Our price is higher. ___, we include insurance.","options":["Although","However","Despite"],"correct":1},{"from":"sales-1-3","kind":"mcq","prompt":"Which question asks about a problem?","options":["What goes wrong with your deliveries today?","What is your company's full name and address?","How long is the catalogue you would like to get?"],"correct":0}]},"explain":{"id":"c-sales-4-1-e","course":"sales","unit":"sales-4-1","type":"explain","level":"B1","title":{"en":"Handling a complaint","tr":"Şikâyeti ele almak","fa":"رسیدگی به شکایت"},"objective":{"en":"After this lesson, you can listen to a complaint, summarise it, apologise clearly, agree a fix, and pass it on to your team.","tr":"Bu dersin sonunda bir şikâyeti dinleyebilecek, özetleyebilecek, açıkça özür dileyebilecek, çözümde anlaşabilecek ve ekibine aktarabileceksin.","fa":"بعد از این درس می‌توانی به یک شکایت گوش بدهی، خلاصه‌اش کنی، روشن عذرخواهی کنی، روی راه‌حل توافق کنی و آن را به تیمت منتقل کنی."},"hook":{"en":"When a customer complains, listen first, then fix the problem with a date. Explaining too early sounds like an excuse, and an ignored complaint can lose the account.","tr":"Müşteri şikâyet ettiğinde önce dinle, sonra sorunu tarihli bir çözümle gider. Erken açıklama bahane gibi duyulur; görmezden gelinen şikâyet müşteriyi kaybettirebilir.","fa":"وقتی مشتری شکایت می‌کند، اول گوش بده و بعد مشکل را با یک تاریخ مشخص حل کن. توضیح زودهنگام شبیه بهانه است و شکایتی که نادیده گرفته شود می‌تواند باعث شود مشتری را از دست بدهی."},"stats":[{"label":{"en":"Key points","tr":"Ana nokta","fa":"نکته‌ی اصلی"},"value":"3"},{"label":{"en":"Key phrases","tr":"Anahtar ifade","fa":"عبارت کلیدی"},"value":"4"},{"label":{"en":"Practice tasks","tr":"Alıştırma","fa":"تمرین"},"value":"3"}],"points":[{"eyebrow":{"en":"The sales skill","tr":"Satış becerisi","fa":"مهارت فروش"},"head":{"en":"Four moves for any complaint","tr":"Her şikâyet için dört adım","fa":"چهار قدم برای هر شکایت"},"steps":[{"en":"Let them finish. If you explain too early, it sounds like an excuse.","tr":"Bitirmelerine izin ver. Erken açıklarsan bahane gibi duyulur.","fa":"بگذار حرفشان تمام شود. اگر زود توضیح بدهی شبیه بهانه است.","ex":"Please go on. What else happened?"},{"en":"Summarise it in their words, and check, so you get the facts right.","tr":"Onların sözleriyle özetle ve kontrol et; böylece gerçekleri doğru öğrenirsin.","fa":"با کلمه‌های خودشان خلاصه کن و بپرس درست است یا نه تا واقعیت‌ها را درست بفهمی.","ex":"So 40 cartons arrived damaged. Is that right?"},{"en":"Say sorry for the exact thing. Blame nobody until you have checked the facts.","tr":"Tam olarak o şey için özür dile. Gerçekleri kontrol etmeden kimseyi suçlama.","fa":"برای همان موضوع مشخص عذرخواهی کن. تا واقعیت‌ها را بررسی نکرده‌ای کسی را مقصر ندان.","ex":"I'm sorry about the damaged cartons."},{"en":"Agree the fix, the date and who does it. Keep that promise: it rebuilds trust.","tr":"Çözümü, tarihi ve kimin yapacağını kararlaştır. Bu sözü tut: güveni bu geri getirir.","fa":"راه‌حل، تاریخ و مسئولش را مشخص کن. به این قول عمل کن: این کار اعتماد را برمی‌گرداند.","ex":"We'll ship 40 new cartons by Friday. I'll call you then."}]},{"eyebrow":{"en":"The language it needs","tr":"Bunun için gereken dil","fa":"زبانی که لازم دارد"},"head":{"en":"Passing on a complaint: She said..., She told me..., She asked if...","tr":"Bir şikâyeti aktarmak: She said..., She told me..., She asked if...","fa":"شکایت را به تیم منتقل کن: She said...، She told me...، She asked if..."},"steps":[{"en":"said + her words; told + person + her words.","tr":"said + onun sözleri; told + kişi + onun sözleri.","fa":"بعد از said خود حرف می‌آید؛ بعد از told اول شخص و بعد حرف.","ex":"She said the cartons were wet. She told me the cartons were wet."},{"en":"Never 'said me': use 'told me' or 'said to me'.","tr":"Asla 'said me' değil: 'told me' ya da 'said to me'.","fa":"هرگز said me نگو؛ بگو told me یا said to me.","ex":"She told me the goods were new."},{"en":"Questions: asked if, or asked + question word, statement order.","tr":"Sorular: asked if ya da asked + soru kelimesi, düz cümle sırası.","fa":"در سؤال‌ها asked if می‌آید، یا asked با کلمه‌ی پرسشی؛ و بعدش ترتیب جمله‌ی خبری.","ex":"She asked if we would pay for the damage."},{"en":"Tenses usually move back: will to would, is to was.","tr":"Zamanlar genellikle geri kayar: will'den would'a, is'ten was'a.","fa":"زمان‌ها معمولاً یک قدم عقب می‌روند: will می‌شود would و is می‌شود was.","ex":"She said she would send photos."}],"table":{"headers":{"en":["She said (her words)","You pass it on"],"tr":["Söylediği (kendi sözleri)","Senin aktarman"],"fa":["حرف خودش","انتقال تو"]},"rows":[["\"The cartons are wet.\"","She said the cartons were wet."],["\"The goods are new.\"","She told me the goods were new."],["\"Will you pay for them?\"","She asked if we would pay for them."],["\"Does anyone check the boxes?\"","She asked if anyone checked the boxes."]]},"tip":{"en":"Turkish 'bana dedi ki' and Persian «به من گفت» put the person after 'said', so learners write 'said me'. In English, 'told' takes the person; 'said' does not.","tr":"Türkçede 'bana dedi ki' deriz; bu yüzden İngilizcede 'said me' yazılıyor. İngilizcede kişiyi told alır: told me. said doğrudan kişi almaz.","fa":"در فارسی می‌گوییم «به من گفت»؛ برای همین خیلی از ما می‌نویسیم said me. در انگلیسی شخص بعد از told می‌آید: told me. بعد از said شخص مستقیم نمی‌آید."},"wrong":"She asked me if can we replace the box.","right":"She asked me if we could replace the box."},{"eyebrow":{"en":"At work","tr":"İş yerinde","fa":"در محیط کار"},"head":{"en":"After the fix","tr":"Çözümden sonra","fa":"بعد از حل مشکل"},"body":{"en":"Pass the facts to your team in the customer's words, so nobody asks the customer again. Find the cause and change one thing. Check your refund, replacement and insurance rules before you promise money.","tr":"Bilgileri ekibine müşterinin sözleriyle aktar ki kimse müşteriye yeniden sormasın. Nedeni bul ve bir şeyi değiştir. Para sözü vermeden önce iade, değişim ve sigorta kurallarını kontrol et.","fa":"واقعیت‌ها را با حرف‌های خود مشتری به تیمت منتقل کن تا کسی دوباره از او نپرسد. علت را پیدا کن و یک چیز را تغییر بده. قبل از قول مالی، قوانین بازگرداندن پول، تعویض و بیمه را بررسی کن."},"phrases":[{"phrase":"Let me make sure I have this right.","meaning":{"en":"Starts your summary.","tr":"Özetini başlatır.","fa":"خلاصه‌ات را شروع می‌کند."}},{"phrase":"I'm sorry about ...","meaning":{"en":"Says sorry for the exact thing.","tr":"Tam olarak o şey için özür diler.","fa":"برای همان موضوع مشخص عذرخواهی می‌کند."}},{"phrase":"She told me that ...","meaning":{"en":"Passes on the customer's words.","tr":"Müşterinin sözlerini aktarır.","fa":"حرف مشتری را منتقل می‌کند."}},{"phrase":"replacement","meaning":{"en":"A new product sent instead of a bad one.","tr":"yenisiyle değişim, yedek ürün.","fa":"کالای جایگزین"}}]}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"From excuse to fix","tr":"Bahaneden çözüme","fa":"از بهانه تا راه‌حل"},"item":"A buyer says 40 cartons arrived damaged. Your reply: It's not our fault. The carrier must have dropped them. You should call them. Your facts: you can send 40 new ones by Friday; you need two photos for the carrier claim.","answer":"I'm sorry about the damaged cartons. Could you send me two photos today? We'll send 40 new ones by Friday and handle the claim with the carrier ourselves.","walk":[{"en":"Don't send the customer to someone else. That doubles the work for them.","tr":"Müşteriyi başkasına gönderme. Bu onun işini iki katına çıkarır.","fa":"مشتری را پیش کس دیگری نفرست. این کار زحمتش را دو برابر می‌کند."},{"en":"Ask only for what you really need to check the facts.","tr":"Yalnızca gerçekleri kontrol etmek için gerçekten gereken şeyi iste.","fa":"فقط چیزی را بخواه که برای بررسی واقعیت‌ها واقعاً لازم است."},{"en":"Give a fair fix and a date, and take the work on yourself.","tr":"Adil bir çözüm ve tarih ver, işi kendin üstlen.","fa":"راه‌حل منصفانه و تاریخ بده و کار را خودت به عهده بگیر."}]},"quick":{"prompt":"Customers stay more loyal when solving a problem takes ___ effort from them.","options":["less","more","extra"],"correct":0,"why":{"en":"less: don't make them repeat the story or call three people. Take the work on yourself.","tr":"less: hikâyeyi tekrar ettirme ya da üç kişiyi aratma. İşi kendin üstlen.","fa":"جواب less است: مجبورشان نکن ماجرا را تکرار کنند یا به سه نفر زنگ بزنند. کار را خودت به عهده بگیر."}},"remember":{"en":"Listen, summarise, sorry, fix with a date. You can now turn a complaint into a clear fix and pass the facts to your team.","tr":"Dinle, özetle, özür dile, tarihli çözüm sun. Artık bir şikâyeti net bir çözüme çevirebilir ve bilgileri ekibine aktarabilirsin.","fa":"گوش بده، خلاصه کن، عذرخواهی کن و راه‌حل را با تاریخ بگو. حالا می‌توانی شکایت را به راه‌حلی روشن تبدیل کنی و واقعیت‌ها را به تیمت منتقل کنی."},"b2Point":{"eyebrow":{"en":"B2 track","tr":"B2 yolu","fa":"مسیر B2"},"head":{"en":"What we did about it: offered to, apologised for, agreed to","tr":"Bu konuda ne yaptık: offered to, apologised for, agreed to","fa":"چه کردیم: offered to، apologised for، agreed to"},"steps":[{"en":"offer / promise / agree + to + verb.","tr":"offer / promise / agree + to + fiil.","fa":"بعد از offer، promise و agree اول to می‌آید و بعد فعل.","ex":"We offered to replace the cartons."},{"en":"apologise + for + -ing.","tr":"apologise + for + -ing.","fa":"بعد از apologise for فعل با ing می‌آید.","ex":"She apologised for sending the wrong label."},{"en":"suggest + -ing (or suggest that + clause).","tr":"suggest + -ing (ya da suggest that + yan cümle).","fa":"بعد از suggest فعل با ing می‌آید، یا that و یک جمله.","ex":"He suggested changing the pallet."}],"table":{"headers":{"en":["Verb","Pattern","Example"],"tr":["Fiil","Kalıp","Örnek"],"fa":["فعل","الگو","مثال"]},"rows":[["offer / promise / agree","+ to + verb","We offered to replace the cartons."],["apologise","+ for + -ing","She apologised for sending the wrong label."],["suggest","+ -ing","He suggested changing the pallet."]]},"body":{"en":"B2: in the report or the email, use two reporting verbs (for example 'offered to', 'apologised for').","tr":"B2: raporda ya da e-postada iki aktarma fiili kullan (örneğin 'offered to', 'apologised for').","fa":"مسیر B2: در گزارش یا ایمیل دو فعل نقل‌قول به کار ببر (مثلاً offered to و apologised for)."}}}}; })(globalThis.COURSE_FILES = globalThis.COURSE_FILES || {});
